const SENIOR_RATES={10:50,11:80,12:100};
let seniorRound=null;
function seniorHub(){if(game||live||quiz){toast('Finish or leave your adventure before starting a Senior Challenge.');return}openModal(`${topModal('OPTIONAL EXTENSION · OLDER STUDENTS')}<h2 id="modal-title">Senior Challenge</h2><p class="sub">Choose Year 10, 11 or 12 practice. Every challenge has five questions, with no time limit. Year 10: 50 points; Year 11: 80 points; Year 12: 100 points per correct answer.</p><div class="senior-reward"><b>50 · 80 · 100 BONUS POINTS</b><span>per correct answer by year · every point also earns one credit<br>Up to 500 points per challenge · no points deducted for mistakes</span></div><div class="senior-year-grid">${[10,11,12].map(year=>`<button class="senior-year" data-senior-year="${year}"><small>YEAR</small><b>${year}</b><span>${year===10?'Algebra, science & critical reading':year===11?'Functions, reasoning & senior science':'Calculus, evidence & advanced concepts'}</span><em>${SENIOR_RATES[year]} points / correct · ${SENIOR_BANK[year].length} questions & variations</em></button>`).join('')}</div><p class="notice">Total bonus points: <b>${profile.seniorPoints||0}</b> · Correct: ${profile.seniorCorrect||0}/${profile.seniorAttempts||0}. This extension does not skip locked game stages.</p><p class="notice">Original supplementary practice; subject sequences vary between schools. <a href="${SENIOR_REFERENCE.url}" target="_blank" rel="noopener">Senior mathematics reference ↗</a></p>`)}
function startSenior(year){if(!SENIOR_BANK[year]||game||live||quiz)return;profile.seniorHistory??={};const items=shuffle([...SENIOR_BANK[year]]),unseen=items.filter(q=>!profile.seniorHistory[q.id]),seen=items.filter(q=>profile.seniorHistory[q.id]).sort((a,b)=>profile.seniorHistory[a.id]-profile.seniorHistory[b.id]);const mixed=[...unseen,...seen],families=new Set(),chosen=[];for(const q of (unseen.length>=5?unseen:mixed))if(!families.has(q.field)){chosen.push(q);families.add(q.field);if(chosen.length===5)break}for(const q of mixed)if(chosen.length<5&&!chosen.includes(q)&&!chosen.some(p=>p.family===q.family))chosen.push(q);for(const q of mixed)if(chosen.length<5&&!chosen.includes(q))chosen.push(q);seniorRound={year,deck:chosen,pos:0,right:0,answered:false};showSeniorQuestion()}
function showSeniorQuestion(){const r=seniorRound;if(!r)return;const q=r.deck[r.pos];r.answered=false;r.options=shuffle((qualityNumberOptions([q.prompt,q.options,0],q.id)||q.options).map((text,index)=>({text,index})));profile.seniorHistory??={};profile.seniorHistory[q.id]=Date.now();save();openModal(`${topModal('SENIOR CHALLENGE · '+(r.pos+1)+' / 5')}<span class="difficulty-tag">YEAR ${r.year} · ${q.field.toUpperCase()}</span><h2 id="modal-title">${q.prompt}</h2><div class="answers">${r.options.map((o,i)=>`<button class="answer" data-senior-answer="${i}"><span>${String.fromCharCode(65+i)}</span>${o.text}</button>`).join('')}</div><div id="senior-feedback" aria-live="polite"></div><p class="hint">${r.right*(SENIOR_RATES[r.year]||100)} bonus points earned · No time limit</p>`)}
function answerSenior(index){const r=seniorRound;if(!r||r.answered||!Number.isInteger(index)||index<0||index>=4)return;r.answered=true;const q=r.deck[r.pos],correct=r.options[index].index===0;r.right+=Number(correct);profile.seniorAttempts=(profile.seniorAttempts||0)+1;if(correct){profile.seniorCorrect=(profile.seniorCorrect||0)+1;profile.seniorPoints=(profile.seniorPoints||0)+(SENIOR_RATES[r.year]||100);profile.coins+=(SENIOR_RATES[r.year]||100)}save();document.querySelectorAll('[data-senior-answer]').forEach((b,i)=>{b.disabled=true;b.classList.toggle('correct',r.options[i].index===0);b.classList.toggle('wrong',i===index&&!correct)});document.querySelector('#senior-feedback').innerHTML=`<div class="feedback ${correct?'correct-feedback':'wrong-feedback'}"><b>${correct?'Correct! +'+SENIOR_RATES[r.year]+' bonus points · +'+SENIOR_RATES[r.year]+' credits':'Keep going — no points deducted.'}</b><p>${q.why}</p><p>Correct answer: <strong>${q.options[0]}</strong></p></div><button class="primary" data-senior-next>${r.pos===4?'See challenge results':'Next question →'}</button>`;const hint=document.querySelector('#modal-content .hint');if(hint)hint.textContent=r.right*(SENIOR_RATES[r.year]||100)+' bonus points earned · No time limit';GameAudio.effect(correct?'correct':'wrong')}
function nextSenior(){const r=seniorRound;if(!r?.answered)return;if(++r.pos<5){showSeniorQuestion();return}const score=r.right*(SENIOR_RATES[r.year]||100);seniorRound=null;openModal(`${topModal('SENIOR CHALLENGE COMPLETE')}<div class="results"><div class="result-emblem">★</div><h2 id="modal-title">${score} bonus points earned.</h2><p>Year ${r.year} · ${r.right} / 5 correct</p><div class="match-score">+${score}<small>BONUS POINTS · +${score} CREDITS SAVED</small></div><p class="notice">${SENIOR_RATES[r.year]} points for each correct answer. Rewards have already been saved. Game-stage unlocks come from winning the games.</p><div class="modal-actions"><button class="primary" data-senior-year="${r.year}">Try five more →</button><button class="secondary" data-senior-hub>Choose a year</button><button class="secondary" data-action="close">Back to games</button></div></div>`)}
const seniorHome=home;home=function(){return seniorHome().replace('<section class="field-shortcuts">',`<section class="senior-banner"><div><small>FOR OLDER STUDENTS & CURIOUS CHALLENGERS</small><h2>Ready for a bigger brain workout?</h2><p>Years 10–12 · 5 questions · 50–100 bonus points per correct answer</p></div><button class="primary" data-senior-hub>★ Senior Challenge →</button></section><section class="field-shortcuts">`)};
document.addEventListener('click',event=>{const b=event.target.closest('button');if(!b)return;if(b.hasAttribute('data-senior-hub'))seniorHub();else if(b.dataset.seniorYear)startSenior(Number(b.dataset.seniorYear));else if(b.dataset.seniorAnswer!==undefined)answerSenior(Number(b.dataset.seniorAnswer));else if(b.hasAttribute('data-senior-next'))nextSenior()});
document.querySelector('.playerbar')?.insertAdjacentHTML('afterbegin','<button class="friends-launch" data-senior-hub>★ Senior Challenge</button>');
if(!game&&!window.location.hash.startsWith('#room=')&&!window.location.hash.startsWith('#challenge='))navigate('home');
